<template><v-row justify="center"><v-col cols="12" md="8"><v-card class="content-card pa-7"><div class="d-flex align-center mb-6"><v-avatar color="secondary" size="54" class="mr-4"><v-icon icon="mdi-account"/></v-avatar><div><h1 class="text-h4 font-weight-bold">Mi perfil</h1><div class="text-medium-emphasis">Gestiona los datos de tu cuenta.</div></div></div><AppAlert :message="message" :type="type" @clear="message=''"/><v-form v-model="valid" @submit.prevent="save"><v-text-field v-model.trim="form.full_name" label="Nombre completo" :rules="[v=>v?.length>=3||'Mínimo 3 caracteres']"/><v-text-field v-model.trim="form.username" label="Usuario" :rules="[v=>/^[A-Za-z0-9_.-]{3,}$/.test(v)||'Usuario inválido']"/><div class="mb-4"><span class="text-caption text-medium-emphasis d-block mb-2">Rol asignado</span><v-chip v-for="role in auth.user.roles" :key="role" class="mr-2" color="secondary">{{ role }}</v-chip></div><v-btn type="submit" color="primary" :disabled="!valid" :loading="loading">Guardar cambios</v-btn></v-form><v-divider class="my-8"/><h2 class="text-h5 font-weight-bold mb-4">Cambiar contraseña</h2><v-form v-model="passwordValid" @submit.prevent="changePassword"><v-text-field v-model="passwordForm.current_password" label="Contraseña actual" type="password" :rules="[v=>!!v||'Obligatoria']"/><PasswordFields v-model="passwordForm.new_password" label="Nueva contraseña"/><v-btn type="submit" color="secondary" :disabled="!passwordValid">Actualizar contraseña</v-btn></v-form></v-card></v-col></v-row></template>
<script setup>import{ref}from'vue';import api from'../services/api';import{useAuthStore}from'../stores/auth';import AppAlert from'../components/AppAlert.vue';import PasswordFields from'../components/PasswordFields.vue';const auth=useAuthStore(),form=ref({...auth.user}),passwordForm=ref({current_password:'',new_password:''}),valid=ref(false),passwordValid=ref(false),loading=ref(false),message=ref(''),type=ref('success');async function save(){loading.value=true;try{const{data}=await api.patch(`/users/${auth.user.id}`,form.value);auth.user=data;localStorage.setItem('user',JSON.stringify(data));message.value='Perfil actualizado';type.value='success'}catch(e){message.value=e.response?.data?.detail||'No fue posible guardar';type.value='error'}finally{loading.value=false}}async function changePassword(){try{await api.post('/auth/change-password',passwordForm.value);passwordForm.value={current_password:'',new_password:''};message.value='Contraseña actualizada';type.value='success'}catch(e){message.value=e.response?.data?.detail||'No fue posible cambiar la contraseña';type.value='error'}}</script>
